def slugify(text: str) -> str:
    """Convert text to a lowercase slug with max 60 characters."""
    try:
        if not isinstance(text, str):
            return ""

        words = []
        current = []

        for ch in text:
            if ch.isalpha() or ch.isdigit():
                current.append(ch)
            elif current:
                word = "".join(current).lower()
                if word:
                    words.append(word)
                current.clear()

        if current:
            word = "".join(current).lower()
            if word:
                words.append(word)

        result = "-".join(words)
        if len(result) <= 60:
            return result

        kept = []
        length = 0

        for word in words:
            extra = len(word) if not kept else len(word) + 1

            if length + extra <= 60:
                kept.append(word)
                length += extra
            else:
                if not kept:
                    return word[:60]
                break

        return "-".join(kept)

    except Exception:
        return ""
