import operator


def chunked(items, size):
    """Разбивает итерабельный объект на списки длины не больше size."""
    if isinstance(size, bool):
        raise ValueError("size must be a positive integer")

    try:
        size = operator.index(size)
    except TypeError as exc:
        raise ValueError("size must be a positive integer") from exc

    if size <= 0:
        raise ValueError("size must be a positive integer")

    result = []
    chunk = []

    for item in items:
        chunk.append(item)
        if len(chunk) == size:
            result.append(chunk)
            chunk = []

    if chunk:
        result.append(chunk)

    return result
```

