def merge_intervals(intervals):
    """Merge overlapping and touching intervals, returning sorted tuples."""
    if not intervals:
        return []

    normalized = []
    for interval in intervals:
        start, end = interval
        if start > end:
            raise ValueError(
                f"Invalid interval: start={start}, end={end} "
                "(start must be less than or equal to end)"
