import time
import threading
from typing import Any, Callable, Dict, Optional


class RateLimiter:
    _EPS = 1e-9

    def __init__(
        self,
        rate: int,
        per_seconds: float,
        clock: Optional[Callable[[], float]] = None,
    ) -> None:
        if isinstance(rate, bool) or not isinstance(rate, int) or rate <= 0:
            raise ValueError("rate must be a positive integer")
        if (
            isinstance(per_seconds, bool)
            or not isinstance(per_seconds, (int, float))
            or per_seconds <= 0
        ):
            raise ValueError("per_seconds must be positive")

        self._rate = rate
        self._capacity = rate
        self._per_seconds = float(per_seconds)
        self._clock = clock if clock is not None else time.monotonic

        self._lock = threading.Lock()
        self._buckets: Dict[Any, Dict[str, float]] = {}

    def _get_bucket_locked(self, key: Any, now: float) -> Dict[str, float]:
        bucket = self._buckets.get(key)
        if bucket is None:
            bucket = {
                "tokens": float(self._capacity),
                "last": now,
            }
            self._buckets[key] = bucket
        return bucket

    def _refill_locked(self, bucket: Dict[str, float], now: float) -> None:
        elapsed = now - bucket["last"]

        if elapsed > 0:
            bucket["tokens"] = min(
                float(self._capacity),
                bucket["tokens"]
                + elapsed * float(self._rate) / self._per_seconds,
            )
            bucket["last"] = now
        elif elapsed < 0:
            # Non-monotonic clock: do not create tokens from a backwards jump.
            bucket["last"] = now

    def allow(self, key: Any, cost: int = 1) -> bool:
        if isinstance(cost, bool) or not isinstance(cost, int) or cost <= 0:
            raise ValueError("cost must be a positive integer")
        if cost > self._rate:
            raise ValueError("cost cannot exceed rate")

        with self._lock:
            now = self._clock()
            bucket = self._get_bucket_locked(key, now)
            self._refill_locked(bucket, now)

            if bucket["tokens"] + self._EPS >= cost:
                bucket["tokens"] = max(0.0, bucket["tokens"] - cost)
                return True
            return False

    def state(self, key: Any) -> Dict[str, Any]:
        with self._lock:
            now = self._clock()
            bucket = self._get_bucket_locked(key, now)
            self._refill_locked(bucket, now)

            return {
                "tokens": round(max(0.0, bucket["tokens"]), 3),
                "capacity": self._capacity,
            }

    def reset(self, key: Any) -> None:
        with self._lock:
            now = self._clock()
            self._buckets[key] = {
                "tokens": float(self._capacity),
                "last": now,
            }
